import java.util.Objects;

class Money {
    private double amount;
    private String currency;

    public Money(double amount, String currency) {
        this.amount = amount;
        this.currency = currency;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        Money other = (Money) obj;
        return Double.compare(amount, other.amount) == 0 &&
               Objects.equals(currency, other.currency);
    }
}

public class IdentityVsLogicalDemo {
    public static void main(String[] args) {
        Money m1 = new Money(20.0, "USD");
        Money m2 = new Money(20.0, "USD");

        // 1. Identity Check (==)
        System.out.println("m1 == m2 (Identity):          " + (m1 == m2)); // false

        // 2. Logical Equality Check (.equals)
        System.out.println("m1.equals(m2) (Logical):       " + m1.equals(m2)); // true

        // 3. System Identity Hash Code (raw memory-derived hash)
        System.out.println("m1 System Hash: " + System.identityHashCode(m1));
        System.out.println("m2 System Hash: " + System.identityHashCode(m2));
    }
}

