import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.Map;

class ColorCode {
    private String hex;
    public ColorCode(String hex) { this.hex = hex; }
    @Override
    public boolean equals(Object obj) {
        return (obj instanceof ColorCode) && ((ColorCode) obj).hex.equals(this.hex);
    }
    @Override
    public int hashCode() { return hex.hashCode(); }
}

public class IdentityMapDemo {
    public static void main(String[] args) {
        ColorCode c1 = new ColorCode("#FF0000");
        ColorCode c2 = new ColorCode("#FF0000");

        // Standard HashMap uses .equals() and .hashCode()
        Map<ColorCode, String> standardMap = new HashMap<>();
        standardMap.put(c1, "Red-1");
        standardMap.put(c2, "Red-2"); // Overwrites c1 because c1.equals(c2)!
        System.out.println("Standard HashMap size: " + standardMap.size()); // 1

        // IdentityHashMap uses == and System.identityHashCode()
        Map<ColorCode, String> identityMap = new IdentityHashMap<>();
        identityMap.put(c1, "Red-1");
        identityMap.put(c2, "Red-2"); // Preserves both because c1 != c2!
        System.out.println("IdentityHashMap size:  " + identityMap.size()); // 2
    }
}

