import java.util.Objects;

class CurrencyRate {
    private final String pair;
    private final double rate;

    public CurrencyRate(String pair, double rate) {
        this.pair = pair;
        this.rate = rate;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        CurrencyRate other = (CurrencyRate) obj;
        return Double.compare(this.rate, other.rate) == 0 &&
               Objects.equals(this.pair, other.pair);
    }

    @Override
    public String toString() {
        return pair + " @ " + rate;
    }
}

public class RateApp {
    public static void main(String[] args) {
        CurrencyRate r1 = new CurrencyRate("EUR/USD", 1.0850);
        CurrencyRate r2 = new CurrencyRate("EUR/USD", 1.0850);

        System.out.println("Identity equal (==): " + (r1 == r2));
        System.out.println("Logical equal (.equals): " + r1.equals(r2));
    }
}

import java.util.HashMap;
import java.util.IdentityHashMap;
