import java.util.Objects;

class ConfigNode {
    private String nodeName;
    public ConfigNode(String nodeName) {
        this.nodeName = nodeName;
    }
    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        ConfigNode other = (ConfigNode) obj;
        return Objects.equals(nodeName, other.nodeName);
    }
    @Override
    public int hashCode() {
        return Objects.hash(nodeName);
    }
}

public class MapApp {
    public static void main(String[] args) {
        ConfigNode n1 = new ConfigNode("cluster.primary");
        ConfigNode n2 = new ConfigNode("cluster.primary");

        Map<ConfigNode, String> stdMap = new HashMap<>();
        stdMap.put(n1, "Value 1");
        stdMap.put(n2, "Value 2");
        System.out.println("Standard Map size: " + stdMap.size());

        Map<ConfigNode, String> idMap = new IdentityHashMap<>();
        idMap.put(n1, "Value 1");
        idMap.put(n2, "Value 2");
        System.out.println("Identity Map size: " + idMap.size());
    }
}

