import java.util.Objects;

class DiagnosticItem {
    private int id;
    private String tag;

    public DiagnosticItem(int id, String tag) {
        this.id = id;
        this.tag = tag;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        DiagnosticItem other = (DiagnosticItem) obj;
        return id == other.id && Objects.equals(tag, other.tag);
    }

    @Override
    public int hashCode() {
        return Objects.hash(id, tag);
    }
}

class HashDiscrepancyAnalyzer {
    public static void analyze(DiagnosticItem a, DiagnosticItem b) {
        System.out.println("Logical equals: " + a.equals(b));
        System.out.println("Custom Hash matching: " + (a.hashCode() == b.hashCode()));
        System.out.println("Identity Hash matching: " + (System.identityHashCode(a) == System.identityHashCode(b)));
    }
}

public class DiscrepancyApp {
    public static void main(String[] args) {
        DiagnosticItem item1 = new DiagnosticItem(500, "ALPHA");
        DiagnosticItem item2 = new DiagnosticItem(500, "ALPHA");

        HashDiscrepancyAnalyzer.analyze(item1, item2);
    }
}
